// Map state: process each order item in parallel
{
  "ProcessItems": {
    "Type": "Map",
    "ItemsPath": "$.items",
    "MaxConcurrency": 10,
    "Iterator": {
      "StartAt": "ProcessOne",
      "States": {
        "ProcessOne": {
          "Type": "Task",
          "Resource": "arn:aws:lambda:...:processItem",
          "End": true
        }
      }
    },
    "ResultPath": "$.results",
    "Next": "Summarize"
  }
}

# GraphQL schema example
type Query {
  order(id: ID!): Order
  ordersByUser(userId: ID!): [Order]
}
type Mutation {
  createOrder(input: CreateOrderInput!): Order
}
type Subscription {
  onOrderCreated(userId: ID!): Order
    @aws_subscribe(mutations: ["createOrder"])
}
type Order {
  id: ID!
  userId: ID!
  amount: Float!
  status: String!
}
